    private void BeginTelemetryRun()
    {
        maskedSensitiveKeysLogged.Clear();
        CurrentRunTelemetry = new PullACRulesRunTelemetry
        {
            StartedUtc = DateTime.UtcNow
        };

        EmitRunEvent(PullACRulesRunPhase.Startup, PullACRulesRunEventKind.Info, "Run started");
    }

    private int CompleteTelemetryRun(int exitCode)
    {
        if (CurrentRunTelemetry != null)
        {
            CurrentRunTelemetry.ExitCode = exitCode;
            CurrentRunTelemetry.EndedUtc = DateTime.UtcNow;

            EmitRunEvent(
                PullACRulesRunPhase.Finalization,
                exitCode == 0 ? PullACRulesRunEventKind.Info : PullACRulesRunEventKind.Warning,
                string.Format("Run ended with exit code {0}", exitCode));
        }

        return exitCode;
    }

    private void EmitRunEvent(
        PullACRulesRunPhase phase,
        PullACRulesRunEventKind kind,
        string message,
        PullACRulesRunIssueCategory category = PullACRulesRunIssueCategory.General)
    {
        if (CurrentRunTelemetry == null)
            return;

        var evt = new PullACRulesRunEvent
        {
            TimestampUtc = DateTime.UtcNow,
            Phase = phase,
            Kind = kind,
            Category = category,
            Message = message ?? string.Empty
        };

        CurrentRunTelemetry.Events.Add(evt);

        Action<PullACRulesRunEvent> sink = RunTelemetrySink;
        if (sink == null)
            return;

        try
        {
            sink(evt);
        }
        catch (InvalidOperationException ex)
        {
            Log("[Telemetry] Sink callback failed: {0}", ex.Message);
        }
    }

    private void EmitRunArtifact(PullACRulesRunPhase phase, string name, string path, int rowCount, int columnCount)
    {
        if (CurrentRunTelemetry == null)
            return;

        CurrentRunTelemetry.Artifacts.Add(new PullACRulesRunArtifact
        {
            TimestampUtc = DateTime.UtcNow,
            Phase = phase,
            Name = name ?? string.Empty,
            Path = path ?? string.Empty,
            RowCount = rowCount,
            ColumnCount = columnCount
        });
    }

    private static PullACRulesRunPhase ResolvePhaseFromExportName(string baseFileName)
    {
        if (string.IsNullOrWhiteSpace(baseFileName))
            return PullACRulesRunPhase.Finalization;

        if (baseFileName.StartsWith("ACRuleList_", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.ACRuleList;
        if (baseFileName.StartsWith("Page_", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.PageRules;
        if (baseFileName.StartsWith("UDF_", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.UdfRules;
        if (baseFileName.StartsWith("TableInfo_", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.TableInfo;
        if (baseFileName.StartsWith("Fwd_SystemInfo", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.SystemInfo;
        if (baseFileName.StartsWith("Fwd_ResourceTypeConfigs", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.ResourceTypeConfigs;
        if (baseFileName.StartsWith("Fwd_ResourceConfigs", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.ResourceConfigs;
        if (baseFileName.StartsWith("Fwd_ResourcePrivateTree", StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.ResourcePrivateTree;
        if (baseFileName.StartsWith(PullACRulesConstants.ExportNames.PageVariantInventory, StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.PageVariantInventory;
        if (baseFileName.StartsWith(PullACRulesConstants.ExportNames.FieldCatalog, StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.FieldCatalog;
        if (baseFileName.StartsWith(PullACRulesConstants.ExportNames.RuleFieldResolution, StringComparison.OrdinalIgnoreCase))
            return PullACRulesRunPhase.RuleFieldResolution;

        return PullACRulesRunPhase.Finalization;
    }

    private static string ResolveDefaultBinDir()
    {
        var starts = new[]
        {
            Directory.GetCurrentDirectory(),
            AppDomain.CurrentDomain.BaseDirectory
        }
        .Where(path => !string.IsNullOrWhiteSpace(path))
        .Distinct(StringComparer.OrdinalIgnoreCase);

        foreach (string start in starts)
        {
            var dir = new DirectoryInfo(start);
            while (dir != null)
            {
                if (File.Exists(Path.Combine(dir.FullName, "PullACRules.csproj")))
                    return Path.Combine(dir.FullName, "extract_out");

                dir = dir.Parent;
            }
        }

        return Path.Combine(Directory.GetCurrentDirectory(), "extract_out");
    }

    public static string GetStartupConfigPath()
    {
        if (!enablePrompts)
            return defaultPath;

        Console.Write("Enter config path (press Enter for default): ");
        string input = Console.ReadLine();
        return string.IsNullOrWhiteSpace(input) ? defaultPath : input.Trim();
    }

    private static string SafePrintAttr(AttrList attrs, string key)
    {
        return RuleRowBuilder.SafePrintAttr(attrs, key);
    }

    private static string SafeAttrTypeName(AttrList attrs, string key)
    {
        if (attrs == null || string.IsNullOrWhiteSpace(key))
            return string.Empty;

        try
        {
            object attrType = attrs.GetType(key);
            return attrType != null ? Convert.ToString(attrType) ?? string.Empty : string.Empty;
        }
        catch (Exception)
        {
            return string.Empty;
        }
    }

    private string MaskSensitiveValue(string key, string value)
    {
        if (!maskSensitiveValues)
            return value ?? string.Empty;

        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        string normalizedKey = key ?? string.Empty;
        if (!IsSensitiveKey(normalizedKey))
            return value;

        if (maskedSensitiveKeysLogged.Add(normalizedKey))
        {
            EmitRunEvent(
                PullACRulesRunPhase.Finalization,
                PullACRulesRunEventKind.Warning,
                string.Format("Sensitive value masked for key '{0}'", normalizedKey),
                PullACRulesRunIssueCategory.DataProtection);
        }

        return "********";
    }

    private static bool IsSensitiveKey(string key)
    {
        if (string.IsNullOrWhiteSpace(key))
            return false;

        string normalized = key.Trim().ToLowerInvariant();
        return normalized.Contains("password")
            || normalized.Contains("passwd")
            || normalized.Contains("pwd")
            || normalized.Contains("secret")
            || normalized.Contains("token")
            || normalized.Contains("apikey")
            || normalized.Contains("api_key")
            || normalized.Contains("connectionstring")
            || normalized.Contains("connection_string")
            || normalized.Contains("connstring")
            || normalized.Contains("connstr");
    }

    public string LastComparisonReportPath { get; private set; } = string.Empty;

    public int Run(string[] args)
    {
        try
        {
            LastComparisonReportPath = string.Empty;
            BeginTelemetryRun();
            OutputFile.ResetRunState();

            PullACRulesOptions options = PullACRulesOptions.Parse(args);
            if (options.HelpRequested)
            {
                PrintUsage();
                return CompleteTelemetryRun(0);
            }

            ApplyOptions(options);

            foreach (string arg in options.UnrecognizedArgs ?? Array.Empty<string>())
                Log("[Warning] Unrecognized argument ignored: {0}", arg);

            string wizardConfigPath;
            string wizardComparePath;
            ResolveInteractiveInputs(options, out wizardConfigPath, out wizardComparePath);

            activeConfigPath = ResolveActiveConfigPath(options, wizardConfigPath);
            if (!ValidateActiveConfigPath())
                return CompleteTelemetryRun(1);

            EnsureOutputDirectory();
            LogStartupSummary();

            ExecuteExtractionIfRequested(options);
            ExecuteComparisonIfRequested(options, wizardComparePath);
            EmitProbeSummaryIfRequested();
            FinalizeDeferredDiagramRendering();

            return CompleteTelemetryRun(OutputFile.FilesWrittenCount > 0 ? 0 : 2);
        }
        catch (Exception ex)
        {
            Log("Fatal error: {0}", ex);
            EmitRunEvent(
                PullACRulesRunPhase.Finalization,
                PullACRulesRunEventKind.Error,
                string.Format("Fatal error: {0}", ex.Message));

            return CompleteTelemetryRun(1);
        }
    }

    private void ResolveInteractiveInputs(PullACRulesOptions options, out string wizardConfigPath, out string wizardComparePath)
    {
        wizardConfigPath = null;
        wizardComparePath = null;

        if (options != null && options.InteractiveMode)
            RunInteractiveWizard(options, out wizardConfigPath, out wizardComparePath);
    }

    private string ResolveActiveConfigPath(PullACRulesOptions options, string wizardConfigPath)
    {
        if (!string.IsNullOrWhiteSpace(wizardConfigPath))
            return wizardConfigPath;

        if (options != null && !string.IsNullOrWhiteSpace(options.ConfigPathArg))
            return options.ConfigPathArg;

        return GetStartupConfigPath();
    }

    private bool ValidateActiveConfigPath()
    {
        if (string.IsNullOrWhiteSpace(activeConfigPath))
        {
            Log("No config file specified. Pass a path as the first argument or use --wizard.");
            EmitRunEvent(PullACRulesRunPhase.Startup, PullACRulesRunEventKind.Error, "No config file specified");
            return false;
        }

        if (!File.Exists(activeConfigPath))
        {
            Log("Config file not found: {0}", activeConfigPath);
            EmitRunEvent(
                PullACRulesRunPhase.Startup,
                PullACRulesRunEventKind.Error,
                string.Format("Config file not found: {0}", activeConfigPath));
            return false;
        }

        return true;
    }

    private void EnsureOutputDirectory()
    {
        if (!string.IsNullOrWhiteSpace(OutputFile.BinDir))
            return;

        OutputFile.BinDir = !string.IsNullOrWhiteSpace(defaultBinDir)
            ? defaultBinDir
            : Path.Combine(Path.GetDirectoryName(activeConfigPath), "extract_out");
    }

    private void LogStartupSummary()
    {
        Log("[Startup] Config path: {0}", activeConfigPath);
        Log("[Startup] Format: {0}", OutputFile.Format);
        Log("[Startup] Attr mode: {0}, Whitelist: {1}, Key mode: {2}", OutputFile.AttributeMode, OutputFile.WhitelistMode, OutputFile.KeyMode);
        Log("[Startup] Full values mode: {0}", OutputFile.FullValueMode);
        Log("[Startup] Probe mode: {0}, Global resources: {1}", probeMode, includeGlobalResourceExports);
        Log("[Startup] Mask sensitive values: {0}", maskSensitiveValues);
        Log("[Startup] Resource types: {0}", string.Join(",", configuredGlobalResourceTypes ?? Array.Empty<string>()));
        Log("[Startup] Target output directory: {0}", OutputFile.BinDir);
    }

    private void ExecuteExtractionIfRequested(PullACRulesOptions options)
    {
        if (options != null && options.NoExtract)
        {
            Log("[Startup] Extraction skipped (--no-extract)");
            EmitRunEvent(PullACRulesRunPhase.Startup, PullACRulesRunEventKind.Warning, "Extraction skipped via --no-extract");
            return;
        }

        using (var fwd = new Fwd(activeConfigPath))
        {
            EmitRunEvent(PullACRulesRunPhase.Startup, PullACRulesRunEventKind.Info, "Connected to FWD");
            ExecuteExtraction(fwd);
        }
    }

    private void ExecuteComparisonIfRequested(PullACRulesOptions options, string wizardComparePath)
    {
        string comparePath = !string.IsNullOrWhiteSpace(wizardComparePath)
            ? wizardComparePath
            : options != null
                ? options.CompareConfigPath
                : null;

        if (string.IsNullOrWhiteSpace(comparePath))
            return;

        EmitRunEvent(
            PullACRulesRunPhase.Comparison,
            PullACRulesRunEventKind.Info,
            string.Format("Starting comparison against {0}", comparePath));

        RunComparison(activeConfigPath, comparePath);
    }

    private void EmitProbeSummaryIfRequested()
    {
        if (!probeMode)
            return;

        Log("All attribute keys seen ({0}):", allSeenKeys.Count);
        foreach (string key in allSeenKeys.OrderBy(value => value))
            Log("  {0}", key);
    }

    private void FinalizeDeferredDiagramRendering()
    {
        if (OutputFile.DiagramMode != OutputFile.DiagramFormat.Svg || OutputFile.PendingSvgPaths.Count == 0)
            return;

        string scriptPath = MermaidRenderer.WriteRenderScript(OutputFile.PendingSvgPaths, OutputFile.BinDir);
        Log("[Mermaid] {0} SVG render job(s) deferred.", OutputFile.PendingSvgPaths.Count);
        Log("[Mermaid] Run this script to generate SVG files:");
        Log("[Mermaid]   {0}", scriptPath);
    }

    public static int Main(string[] args)
    {
        PullACRulesOptions options = PullACRulesOptions.Parse(args);
        if (options.UiMode && !options.HelpRequested)
            return PullACRulesUiHost.Run(args);

        return new PullACRules().Run(args);
    }
